// Read enforces ordering: must be called after Open. The stub
// panics when called out of order.
//
// Dispatches via OnRead through the standard chain
// (fault → Func → fallback → FailUnexpectedCall) and records the
// call before returning.
func (s *DirectivesStub) Read(ctx context.Context, key string) (interfaces.Record, error) {
	s.order.AssertAfter("Read", "Open")
	s.OnRead.SleepLatency()
	defer s.order.Record("Read")
	call := DirectivesStubReadCall{Ctx: ctx, Key: key}
	if fired, faultErr := s.OnRead.ShouldFaultFor(call); fired {
		call.Err = faultErr
		s.OnRead.Record(call)
		return interfaces.Record{}, faultErr
	}
	if s.OnRead.fn != nil {
		var v0 interfaces.Record
		var err error
		v0, err = s.OnRead.fn(ctx, key)
		call.Result = v0
		call.Err = err
		s.OnRead.Record(call)
		return v0, err
	}
	if s.OnRead.fallback != nil {
		f := s.OnRead.fallback
		call.Result = f.Result
		call.Err = f.Err
		s.OnRead.Record(call)
		return f.Result, f.Err
	}
	s.OnRead.FailUnexpectedCall(call)
	s.OnRead.Record(call)
	return interfaces.Record{}, nil
}

